        var result = new Instance(wgpuCreateInstance(null));
        return result;
    }

    public static SupportedInstanceFeatures GetInstanceFeatures()
    {
        var n_features = new WGPUSupportedInstanceFeatures();
        wgpuGetInstanceFeatures(&n_features);
        var value = Marshalling.FromNative(n_features);
        wgpuSupportedInstanceFeaturesFreeMembers(n_features);
        return value;
    }

    public static bool HasInstanceFeature(InstanceFeatureName feature)
    {
        var result = wgpuHasInstanceFeature(feature) != 0;
        return result;
    }

    public static Status GetInstanceLimits(out InstanceLimits limits)
    {
        var n_limits = new WGPUInstanceLimits();
        var result = wgpuGetInstanceLimits(&n_limits);
        limits = Marshalling.FromNative(n_limits);
        return result;
    }

}

